#!/bin/sh
# The theme pipeline, live: the brief's fixed palette, a palette taken from the wallpaper
# (a staged one, and one *really* generated by Matugen from the current wallpaper), the
# user's overrides, a wallpaper whose text would be unreadable (lifted, not refused), and a
# theme an override makes unreadable — which must be refused whole, leaving the last good one
# on screen.
#
# It also proves the whole point of keeping the layers apart: a palette change touches
# colour facts only. Layout, motion, behaviour and workspace settings must be untouched,
# and settings.json must not be rewritten by a wallpaper change.
#
# Backs up and restores settings.json, settings.known-good.json and palette.json.
# Run from anywhere: tests/theme.sh      (stop mooi first: bin/mooi stop)
set -u
root=$(cd "$(dirname "$0")/.." && pwd)
dir="${XDG_DATA_HOME:-$HOME/.local/share}/pleamar/mooi"
file="$dir/settings.json"
good="$dir/settings.known-good.json"
palette="$dir/palette.json"
log=${TMPDIR:-/tmp}/mooi-theme.$$.log
fail=0; n=0
for f in "$file" "$good" "$palette"; do cp "$f" "$f.bak-theme-test" 2>/dev/null || true; done
restore() {
    for f in "$file" "$good" "$palette"; do
        if [ -e "$f.bak-theme-test" ]; then mv "$f.bak-theme-test" "$f"; else rm -f "$f"; fi
    done
}
trap restore EXIT

say() { pleamar --say mooi "$@"; }
get() { say "get $1" 2>&1 | tail -1; }
check() { n=$((n + 1)); got=$(get "$1"); if [ "$got" = "$2" ]; then echo "  ok    $3"
    else echo "  FAIL  $3 ($1 = '$got', expected '$2')"; fail=$((fail + 1)); fi; }
near() { # name value what    (colour channels are compared with room for rounding)
    n=$((n + 1)); got=$(get "$1")
    if awk -v a="$got" -v b="$2" 'BEGIN { if (a == "") exit 1; d = a - b; if (d < 0) d = -d; exit !(d < 0.002) }'; then
        echo "  ok    $3 ($1 = $got)"
    else echo "  FAIL  $3 ($1 = '$got', expected ~$2)"; fail=$((fail + 1)); fi
}
channel() { # #RRGGBB, which    (1 = red, 2 = green, 3 = blue) → 0..1
    # Plain POSIX awk: gawk's strtonum is not everywhere, and the colour has to be read
    # from the palette file the same way on any machine the suite runs on.
    awk -v hex="$1" -v k="$2" 'BEGIN {
        sub(/^#/, "", hex)
        part = substr(hex, (k - 1) * 2 + 1, 2)
        v = 0
        for (i = 1; i <= 2; i++) v = v * 16 + index("0123456789abcdef", tolower(substr(part, i, 1))) - 1
        printf "%.6f", v / 255
    }'
}
write_settings() { printf '%s' "$1" > "$file"; sleep 0.7; }
# What a token should be, worked out by the same libraries the shell uses (lib/ferro → lib/theme),
# from the palette file as it is now and the theme's source: token, channel (1 r · 2 g · 3 b), source.
expected() {
    cols=$(jq -r '.colours | to_entries | map("[\"" + .key + "\"]=\"" + .value + "\"") | join(",")' "$palette" 2>/dev/null)
    lua5.4 -e "package.path='$root/shell/?.luau;'..package.path
        local ferro, theme = require('lib/ferro'), require('lib/theme')
        local pal = ('$cols' ~= '') and { colours = { $cols } } or nil
        local roles = ferro.resolve('${3:-wallpaper}', pal, 'auto', false, {})
        local c = theme.resolve({}, roles)['$1']
        io.write(string.format('%.6f', ({ c.r, c.g, c.b })[$2]))"
}
start() {
    # Both streams: pleamar logs what it did (including the theme lines the checks read)
    # on stdout, and errors on stderr.
    pleamar --scene "$root/shell/mooi.plm" --no-hud --stall 0 --seconds 60 "$@" > "$log" 2>&1 &
    pid=$!
    for _ in $(seq 1 20); do sleep 0.3; get open >/dev/null 2>&1 && break; done
    sleep 0.5
}

if say "get open" >/dev/null 2>&1; then
    echo "mooi is already running; stop it first (bin/mooi stop)"; exit 2
fi
mkdir -p "$dir"

# A palette shaped exactly like the one Matugen writes (theme/palette.json.hbs).
stage_matugen_palette() {
    cat > "$palette" << 'JSON'
{
  "version": 1, "mode": "dark",
  "colours": {
    "surface_dim": "#16130b", "surface_container_low": "#1e1b13",
    "surface_container": "#221f17", "surface_container_high": "#2d2a21",
    "outline_variant": "#4b4639", "outline": "#979080",
    "on_surface": "#e9e2d4", "on_surface_variant": "#cec6b4",
    "primary": "#dfc56d", "error": "#ffb4ab"
  }
}
JSON
}

echo "the brief's palette is what shows unless asked otherwise"
rm -f "$palette"
write_settings '{ "version": 1 }'
start
check theme_error false "a clean start has nothing wrong to report"
near c_accent_primary_r "$(expected accent.primary 1)" "accent.primary is mooi's own phosphor (r)"
near c_accent_primary_g "$(expected accent.primary 2)" "…(g)"
near c_bg_primary_r "$(expected bg.primary 1)" "bg.primary is mooi's own hull (r)"
check previews true "other settings are where they were"

echo "asked for the wallpaper and there is no palette yet"
stage_matugen_palette; rm -f "$palette"
write_settings '{ "version": 1, "theme": { "source": "wallpaper" } }'
check theme_error false "a missing palette is not an error"
near c_accent_primary_r "$(expected accent.primary 1)" "mooi's own palette keeps showing"
if grep -q 'bar · colours · fixed (the palette has no colours)' "$log"; then echo "  ok    the log says why"; else
    echo "  FAIL  the log does not say why"; fail=$((fail + 1)); fi

echo "a palette from the wallpaper fills the tokens"
stage_matugen_palette
sleep 0.8
check theme_error false "the palette passes"
near c_accent_primary_r "$(expected accent.primary 1)" "accent.primary is the phosphor built from the wallpaper's primary (r)"
near c_accent_primary_g "$(expected accent.primary 2)" "…(g)"
near c_accent_primary_b "$(expected accent.primary 3)" "…(b)"
near c_bg_primary_r "$(expected bg.primary 1)" "bg.primary is the hull, from the wallpaper's surfaces"
near c_fg_primary_r "$(expected fg.primary 1)" "fg.primary is the phosphor too"
near c_selection_bg_r "$(expected selection.bg 1)" "selection.bg is the well"
if grep -q 'theme · applied' "$log"; then echo "  ok    the log says it applied the wallpaper palette"; else
    echo "  FAIL  the log does not say it applied it"; fail=$((fail + 1)); fi

echo "an override wins over the wallpaper, as the brief's precedence says"
write_settings '{ "version": 1, "theme": { "source": "wallpaper", "overrides": { "accent.primary": "#FF00FF" } } }'
near c_accent_primary_r 1.000000 "accent.primary is the override (r)"
near c_accent_primary_g 0.000000 "…(g)"
near c_accent_primary_b 1.000000 "…(b)"
near c_bg_primary_r "$(expected bg.primary 1)" "the rest is still the wallpaper's"

echo "a palette whose own text roles are unreadable changes nothing: mooi builds its text from the hue and holds it (D27)"
cat > "$palette" << 'JSON'
{
  "version": 1, "mode": "dark",
  "colours": {
    "surface_dim": "#16130b", "surface_container_low": "#1e1b13",
    "surface_container": "#221f17", "surface_container_high": "#2d2a21",
    "outline_variant": "#4b4639", "outline": "#26261f",
    "on_surface": "#1d1a12", "on_surface_variant": "#20201c",
    "primary": "#dfc56d", "error": "#ffb4ab"
  }
}
JSON
sleep 0.8
check theme_error false "no error dot: the wallpaper did nothing wrong"
lifted=$(get c_fg_primary_r)
near c_fg_primary_r "$(expected fg.primary 1)" "fg.primary is the phosphor, not the palette's unreadable text"
near c_accent_primary_r 1.000000 "…and the override that was applied still is"

echo "a theme the user's own override makes unreadable is refused whole (the last good one stays)"
write_settings '{ "version": 1, "theme": { "source": "wallpaper", "overrides": { "accent.primary": "#FF00FF", "fg.primary": "#1d1a12" } } }'
check theme_error true "the Spine's dot says the theme was refused"
near c_fg_primary_r "$lifted" "fg.primary is still the last good theme's"
near c_accent_primary_r 1.000000 "…including the override that was applied"
if grep -q 'theme · refused the palette' "$log"; then echo "  ok    the log says it refused it, and why"; else
    echo "  FAIL  the log does not say it refused it"; fail=$((fail + 1)); fi

echo "a real Matugen run, from the wallpaper on the screen"
# The override is taken back out first: what this section proves is that the palette
# Matugen makes from the real wallpaper is the one mooi paints, with no override on top.
write_settings '{ "version": 1, "theme": { "source": "wallpaper" } }'
before_settings=$(cksum "$file")
rm -f "$palette"
if bin/mooi theme-sync > /tmp/mooi-theme-sync.$$ 2>&1; then
    n=$((n + 1)); echo "  ok    bin/mooi theme-sync wrote a palette ($(head -1 /tmp/mooi-theme-sync.$$))"
else
    n=$((n + 1)); fail=$((fail + 1)); echo "  FAIL  bin/mooi theme-sync failed: $(cat /tmp/mooi-theme-sync.$$)"
fi
rm -f /tmp/mooi-theme-sync.$$
roles=$(jq -r '.colours | keys | length' "$palette" 2>/dev/null)
if [ "$roles" = 13 ]; then echo "  ok    the palette has the thirteen Material roles mooi maps (lib/theme and lib/ferro)"
else echo "  FAIL  the palette has '$roles' roles, expected 13"; fail=$((fail + 1)); fi
real_primary=$(jq -r '.colours.primary' "$palette" 2>/dev/null)
sleep 0.8
check theme_error false "mooi accepts the palette Matugen just made"
near c_accent_primary_r "$(expected accent.primary 1)" "…and paints the phosphor built from its primary ($real_primary)"

echo "a palette change cannot touch anything but colour"
after_settings=$(cksum "$file")
if [ "$before_settings" = "$after_settings" ]; then echo "  ok    settings.json was not rewritten by any palette change"
else echo "  FAIL  a palette change rewrote settings.json"; fail=$((fail + 1)); fi
check ws_max 10 "the workspace map is where it was"
check show_clock true "the clock setting is where it was"
check previews true "the previews setting is where it was"
check phase compact "no island was opened by a theme change"

say quit >/dev/null 2>&1; wait "$pid" 2>/dev/null
echo
echo "$n checks, $fail failed · log $log"
[ "$fail" -eq 0 ]
